ALTER TABLE public.comprovantes ADD COLUMN nota_envio_id uuid REFERENCES public.notas_fiscais(id);
CREATE OR REPLACE FUNCTION private.driver_open_load(_uid uuid,_carga uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM cargas WHERE id=_carga AND motorista_id=private.driver_id(_uid) AND situacao='ativa' AND status<>'finalizada' AND data_finalizacao IS NULL) $$;
REVOKE ALL ON FUNCTION private.driver_open_load(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION private.driver_open_load(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.driver_proof_read(_uid uuid,_proof uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM comprovantes p WHERE p.id=_proof AND p.user_id=_uid AND private.driver_open_load(_uid,coalesce(p.carga_id,(SELECT carga_id FROM notas_fiscais WHERE id=coalesce(p.nota_envio_id,p.nota_id))))) $$;
REVOKE ALL ON FUNCTION private.driver_proof_read(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION private.driver_proof_read(uuid,uuid) TO authenticated;
ALTER POLICY comprovantes_driver_select ON public.comprovantes USING(private.driver_proof_read(auth.uid(),id));
ALTER POLICY comprovantes_obj_driver_select ON storage.objects USING(bucket_id='comprovantes' AND EXISTS(SELECT 1 FROM public.comprovantes p WHERE p.storage_path=name AND private.driver_proof_read(auth.uid(),p.id)));
ALTER POLICY cargas_select_driver ON public.cargas USING(private.driver_open_load(auth.uid(),id));
ALTER POLICY notas_select_driver ON public.notas_fiscais USING(private.driver_open_load(auth.uid(),carga_id));
CREATE OR REPLACE FUNCTION public.tg_driver_proof_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE load_id uuid; BEGIN IF TG_OP='UPDATE' THEN IF NEW.nota_envio_id IS DISTINCT FROM OLD.nota_envio_id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.motorista_id IS DISTINCT FROM OLD.motorista_id OR NEW.storage_path IS DISTINCT FROM OLD.storage_path THEN RAISE EXCEPTION 'Identidade do envio preservada'; END IF; RETURN NEW; END IF; IF private.can_write(auth.uid()) OR auth.uid() IS NULL THEN RETURN NEW; END IF; IF NEW.nota_envio_id IS NOT NULL THEN SELECT carga_id INTO load_id FROM notas_fiscais WHERE id=NEW.nota_envio_id; IF NEW.carga_id IS NOT NULL AND NEW.carga_id IS DISTINCT FROM load_id THEN RAISE EXCEPTION 'Nota não pertence à carga'; END IF; NEW.carga_id:=load_id; END IF; IF NEW.carga_id IS NOT NULL THEN PERFORM 1 FROM cargas WHERE id=NEW.carga_id FOR SHARE; IF NOT private.driver_open_load(auth.uid(),NEW.carga_id) THEN RAISE EXCEPTION 'Carga finalizada ou não atribuída ao motorista'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER driver_proof_scope BEFORE INSERT OR UPDATE ON public.comprovantes FOR EACH ROW EXECUTE FUNCTION public.tg_driver_proof_scope();
ALTER TABLE public.clientes_agendamento ADD COLUMN apelido text NOT NULL DEFAULT '';
ALTER TABLE public.distancias ADD COLUMN atualizado_por uuid REFERENCES public.profiles(id);
CREATE OR REPLACE FUNCTION public.tg_distance_author() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.cidade:=trim(NEW.cidade); NEW.uf:=upper(trim(NEW.uf)); IF NEW.cidade='' OR NEW.uf !~ '^[A-Z]{2}$' OR trim(NEW.fonte)='' THEN RAISE EXCEPTION 'Informe cidade, UF e fonte validada'; END IF; PERFORM pg_advisory_xact_lock(hashtext(lower(NEW.cidade)||NEW.uf)); IF EXISTS(SELECT 1 FROM distancias WHERE lower(trim(cidade))=lower(NEW.cidade) AND upper(trim(uf))=NEW.uf AND id<>NEW.id) THEN RAISE EXCEPTION 'Cidade e UF já cadastradas; edite o registro existente'; END IF; NEW.atualizado_em:=now(); NEW.atualizado_por:=auth.uid(); INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('distancia',NEW.id,'distancia_salva',NEW.cidade||'/'||NEW.uf||' '||NEW.km||' km',auth.uid()); RETURN NEW; END $$;
CREATE TRIGGER distance_author BEFORE INSERT OR UPDATE ON public.distancias FOR EACH ROW EXECUTE FUNCTION public.tg_distance_author();
CREATE OR REPLACE FUNCTION public.tg_client_alias_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.apelido IS DISTINCT FROM OLD.apelido THEN INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('cliente_agendamento',NEW.id,'apelido_alterado',coalesce(OLD.apelido,'')||' → '||NEW.apelido,auth.uid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER client_alias_audit AFTER UPDATE ON public.clientes_agendamento FOR EACH ROW EXECUTE FUNCTION public.tg_client_alias_audit();
CREATE TABLE public.notificacoes_dispensadas(user_id uuid NOT NULL REFERENCES public.profiles(id),evento_chave text NOT NULL CHECK(length(evento_chave) BETWEEN 1 AND 500),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,evento_chave));
GRANT SELECT,INSERT ON public.notificacoes_dispensadas TO authenticated; GRANT ALL ON public.notificacoes_dispensadas TO service_role;
ALTER TABLE public.notificacoes_dispensadas ENABLE ROW LEVEL SECURITY;
CREATE POLICY dismiss_own_read ON public.notificacoes_dispensadas FOR SELECT TO authenticated USING(user_id=auth.uid() AND private.active_user(auth.uid()));
CREATE POLICY dismiss_own_insert ON public.notificacoes_dispensadas FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND private.active_user(auth.uid()));